{
  "votes": [
    {
      "item": "i01",
      "choice": "v1",
      "reason": "La résolution 2026-05-167 adopte explicitement le règlement 645 sur l’occupation et l’entretien des bâtiments à la page 5."
    },
    {
      "item": "i02",
      "choice": "v1",
      "reason": "La résolution 2026-05-175, dont le titre est cité exactement à la page 12, demande à la page 14 la suspension et la révision du projet de règlement, sans en constater l’adoption."
    },
    {
      "item": "i03",
      "choice": "v1",
      "reason": "La page 19 autorise la signature d’une modification de la convention de concession pour l’agrandissement du bâtiment de la halte routière, acte foncier inclus même s’il est non résidentiel."
    },
    {
      "item": "i04",
      "choice": "v2",
      "reason": "Le dispositif de la page 19 autorise expressément la demande 2026-009 « par projet de résolution », sans qualifier cette étape d’adoption définitive ou de second projet."
    },
    {
      "item": "i05",
      "choice": "v1",
      "reason": "La résolution 2026-05-187 autorise à la page 20 le PIIA 2026-010 pour la reconstruction de la maison au 318, chemin de L’Anse-de-Roche."
    },
    {
      "item": "i06",
      "choice": "v1",
      "reason": "La résolution 2026-05-188 autorise à la page 20 le PIIA 2026-008 pour la maison au 99, chemin du Fjord, conformément à la citation proposée."
    },
    {
      "item": "i07",
      "choice": "v1",
      "reason": "La résolution 2026-05-189 autorise à la page 21 le PIIA 2026-007 pour ajouter des panneaux de verre au patio du 322, chemin de L’Anse de Roche et en faire une verrière trois saisons."
    },
    {
      "item": "i08",
      "choice": "v1",
      "reason": "La résolution 2026-05-190 autorise à la page 21 le PIIA 2026-006 pour agrandir le patio à la place de la terrasse actuelle au 295, chemin de L’Anse de Roche."
    },
    {
      "item": "i09",
      "choice": "v1",
      "reason": "La page 22 autorise la dérogation réduisant la marge arrière de huit à deux mètres pour le lot 4 700 841, avec le numéro « 20226-009 » effectivement écrit dans le document."
    },
    {
      "item": "i10",
      "choice": "v1",
      "reason": "La résolution 2026-05-192 autorise à la page 22 la dérogation 2026-011 réduisant la marge arrière de huit à 6,25 mètres derrière le garage attenant sur le lot 4 701 026."
    },
    {
      "item": "i11",
      "choice": "absent",
      "reason": "Le développement du secteur de la rue Dufour est un fait complémentaire attesté, mais la résolution 2026-05-180 accepte un marché de services d’estimation de Stantec, catégorie exclue du rappel."
    },
    {
      "item": "i12",
      "choice": "absent",
      "reason": "Cette proposition reprend exactement la demande de suspension et de révision de la résolution 2026-05-175 déjà couverte par i02, sans objet ni étape distincts, et constitue donc un doublon non crédité."
    }
  ]
}
